   638→			if tt.createParent {
   639→				if err := os.MkdirAll(filepath.Dir(rcFile), 0o755); err != nil {
   640→					t.Fatal(err)
   641→				}
   642→			}
   643→			if tt.preExisting != "" {
   644→				if err := os.WriteFile(rcFile, []byte(tt.preExisting), 0o644); err != nil {
   645→					t.Fatal(err)
   646→				}
   647→			}
   648→
   649→			if err := appendShellCompletion(rcFile, tt.completionLine); err != nil {
   650→				t.Fatalf("appendShellCompletion() error: %v", err)
   651→			}
   652→
   653→			// Verify the file was created and contains the completion line.
   654→			data, err := os.ReadFile(rcFile)
   655→			if err != nil {
   656→				t.Fatalf("reading rc file: %v", err)
   657→			}
   658→			content := string(data)
   659→
   660→			if !strings.Contains(content, shellCompletionComment) {
   661→				t.Errorf("rc file missing comment %q", shellCompletionComment)
