   663→			if !strings.Contains(content, tt.completionLine) {
   664→				t.Errorf("rc file missing completion line %q", tt.completionLine)
   665→			}
   666→			if tt.preExisting != "" && !strings.HasPrefix(content, tt.preExisting) {
   667→				t.Errorf("pre-existing content was overwritten")
   668→			}
   669→
   670→			// Verify parent directory permissions.
   671→			info, err := os.Stat(filepath.Dir(rcFile))
   672→			if err != nil {
   673→				t.Fatalf("stat parent dir: %v", err)
   674→			}
   675→			if !info.IsDir() {
   676→				t.Fatal("parent path is not a directory")
   677→			}
   678→		})
   679→	}
   680→}
