   966→// StageFilesContext describes what type of staging operation this is (for messages).
   967→type StageFilesContext string
   968→
   969→const (
   970→	// StageForSession is used when staging files for a session checkpoint.
   971→	StageForSession StageFilesContext = "session"
   972→	// StageForTask is used when staging files for a task checkpoint.
   973→	StageForTask StageFilesContext = "task"
   974→)
   975→
   976→// StageFiles stages modified, new, and deleted files to the git worktree.
   977→//
   978→// This function handles three categories of file changes:
   979→//  1. Modified files: existing files that have been changed
   980→//  2. New files: files that were created during the session
   981→//  3. Deleted files: files that were removed during the session
   982→//
   983→// Error Handling Strategy:
   984→//   - Individual file staging errors are logged to stderr but don't fail the operation
   985→//   - This ensures that partial staging succeeds even if some files have issues
   986→//   - If a modified file no longer exists, it's treated as a deletion
   987→//
   988→// The stageCtx parameter is used for user-facing messages to indicate whether
   989→// this is staging for a session checkpoint or a task checkpoint.
   990→func StageFiles(worktree *git.Worktree, modified, newFiles, deleted []string, stageCtx StageFilesContext) {
   991→	// Get worktree root for resolving file paths
   992→	// This is critical because fileExists() uses os.Stat() which resolves relative to CWD,
   993→	// but worktree.Add/Remove resolve relative to repo root. If CWD != repo root,
   994→	// fileExists() could return false for existing files, causing worktree.Remove()
   995→	// to incorrectly delete them.
   996→	repoRoot := worktree.Filesystem.Root()
   997→
   998→	// Stage modified files
   999→	for _, file := range modified {
  1000→		// Resolve path relative to repo root for existence check
  1001→		absPath := filepath.Join(repoRoot, file)
  1002→		if fileExists(absPath) {
  1003→			if _, err := worktree.Add(file); err != nil {
  1004→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
  1005→			} else {
  1006→				fmt.Fprintf(os.Stderr, "  Staged: %s\n", file)
  1007→			}
  1008→		} else {
  1009→			// File was deleted - stage the deletion
  1010→			if _, err := worktree.Remove(file); err != nil {
  1011→				fmt.Fprintf(os.Stderr, "  File not found or deleted: %s\n", file)
  1012→			}
  1013→		}
  1014→	}
  1015→
  1016→	// Stage new files
  1017→	if len(newFiles) > 0 {
  1018→		fmt.Fprintf(os.Stderr, "Staging %d new files created during %s:\n", len(newFiles), stageCtx)
  1019→		for _, file := range newFiles {
  1020→			if _, err := worktree.Add(file); err != nil {
  1021→				fmt.Fprintf(os.Stderr, "  Failed to stage %s: %v\n", file, err)
  1022→			} else {
  1023→				fmt.Fprintf(os.Stderr, "  Staged new file: %s\n", file)
  1024→			}
  1025→		}
  1026→	}
  1027→
  1028→	// Stage deleted files
  1029→	for _, file := range deleted {
  1030→		if _, err := worktree.Remove(file); err != nil {
  1031→			fmt.Fprintf(os.Stderr, "  Failed to stage deleted file %s: %v\n", file, err)
  1032→		} else {
  1033→			fmt.Fprintf(os.Stderr, "  Staged deleted file: %s\n", file)
  1034→		}
  1035→	}
  1036→}
