  1038→// getTaskCheckpointFromTree retrieves a task checkpoint from a commit tree.
  1039→// Shared implementation for shadow and linear-shadow strategies.
  1040→func getTaskCheckpointFromTree(ctx context.Context, point RewindPoint) (*TaskCheckpoint, error) {
  1041→	if !point.IsTaskCheckpoint {
  1042→		return nil, ErrNotTaskCheckpoint
  1043→	}
  1044→
  1045→	repo, err := OpenRepository(ctx)
  1046→	if err != nil {
  1047→		return nil, fmt.Errorf("failed to open repository: %w", err)
  1048→	}
  1049→
  1050→	commitHash := plumbing.NewHash(point.ID)
  1051→	commit, err := repo.CommitObject(commitHash)
  1052→	if err != nil {
  1053→		return nil, fmt.Errorf("failed to get commit: %w", err)
  1054→	}
  1055→
  1056→	tree, err := commit.Tree()
  1057→	if err != nil {
  1058→		return nil, fmt.Errorf("failed to get tree: %w", err)
  1059→	}
  1060→
  1061→	// Read checkpoint.json from the tree
  1062→	checkpointPath := point.MetadataDir + "/checkpoint.json"
  1063→	file, err := tree.File(checkpointPath)
  1064→	if err != nil {
  1065→		return nil, fmt.Errorf("failed to find checkpoint at %s: %w", checkpointPath, err)
  1066→	}
  1067→
  1068→	content, err := file.Contents()
  1069→	if err != nil {
  1070→		return nil, fmt.Errorf("failed to read checkpoint: %w", err)
  1071→	}
  1072→
  1073→	var checkpoint TaskCheckpoint
  1074→	if err := json.Unmarshal([]byte(content), &checkpoint); err != nil {
  1075→		return nil, fmt.Errorf("failed to parse checkpoint: %w", err)
  1076→	}
  1077→
  1078→	return &checkpoint, nil
  1079→}
