  1081→// getTaskTranscriptFromTree retrieves a task transcript from a commit tree.
  1082→// Shared implementation for shadow and linear-shadow strategies.
  1083→func getTaskTranscriptFromTree(ctx context.Context, point RewindPoint) ([]byte, error) {
  1084→	if !point.IsTaskCheckpoint {
  1085→		return nil, ErrNotTaskCheckpoint
  1086→	}
  1087→
