  1318→			return desc
  1319→		}
  1320→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
  1321→			return desc
  1322→		}
  1323→		return NoDescription
  1324→	}
  1325→
  1326→	// No metadataDir provided - first try looking at the root of the tree
  1327→	// (used when the tree is already the session directory)
  1328→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
  1329→		return desc
  1330→	}
  1331→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
  1332→		return desc
  1333→	}
