   362→// readCheckpointMetadata reads metadata.json from a checkpoint path on entire/checkpoints/v1.
   363→// With the new format, root metadata.json is a CheckpointSummary with Agents array.
   364→// This function reads the summary and extracts relevant fields into CheckpointInfo,
   365→// also reading session-level metadata for IsTask/ToolUseID fields.
   366→func ReadCheckpointMetadata(tree *object.Tree, checkpointPath string) (*CheckpointInfo, error) {
   367→	metadataPath := checkpointPath + "/metadata.json"
   368→	file, err := tree.File(metadataPath)
   369→	if err != nil {
   370→		return nil, fmt.Errorf("failed to find metadata at %s: %w", metadataPath, err)
   371→	}
   372→
   373→	content, err := file.Contents()
   374→	if err != nil {
   375→		return nil, fmt.Errorf("failed to read metadata: %w", err)
   376→	}
   377→
   378→	// Try to parse as CheckpointSummary first (new format)
   379→	var summary checkpoint.CheckpointSummary
   380→	if err := json.Unmarshal([]byte(content), &summary); err == nil {
   381→		// If we have sessions array, this is the new format
   382→		if len(summary.Sessions) > 0 {
   383→			info := &CheckpointInfo{
   384→				CheckpointID:     summary.CheckpointID,
   385→				CheckpointsCount: summary.CheckpointsCount,
   386→				FilesTouched:     summary.FilesTouched,
   387→				SessionCount:     len(summary.Sessions),
   388→			}
   389→
   390→			// Read all sessions' metadata to populate SessionIDs and get other fields from first session
   391→			var sessionIDs []string
   392→			for i, sessionPaths := range summary.Sessions {
   393→				if sessionPaths.Metadata != "" {
   394→					// SessionFilePaths now contains absolute paths with leading "/"
   395→					// Strip the leading "/" for tree.File() which expects paths without leading slash
   396→					sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
   397→					if sessionFile, err := tree.File(sessionMetadataPath); err == nil {
   398→						if sessionContent, err := sessionFile.Contents(); err == nil {
   399→							var sessionMetadata checkpoint.CommittedMetadata
   400→							if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   401→								sessionIDs = append(sessionIDs, sessionMetadata.SessionID)
   402→								// Use first session for Agent, SessionID, CreatedAt, IsTask, ToolUseID
   403→								if i == 0 {
   404→									info.Agent = sessionMetadata.Agent
   405→									info.SessionID = sessionMetadata.SessionID
   406→									info.CreatedAt = sessionMetadata.CreatedAt
   407→									info.IsTask = sessionMetadata.IsTask
   408→									info.ToolUseID = sessionMetadata.ToolUseID
   409→								}
   410→							}
   411→						}
   412→					}
   413→				}
   414→			}
   415→			info.SessionIDs = sessionIDs
   416→
   417→			return info, nil
   418→		}
   419→	}
   420→
   421→	// Fall back to parsing as CheckpointInfo (old format or direct info)
   422→	var metadata CheckpointInfo
   423→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
   424→		return nil, fmt.Errorf("failed to parse metadata: %w", err)
   425→	}
   426→
   427→	return &metadata, nil
   428→}
