   496→// ReadAgentTypeFromTree reads the agent type from a checkpoint's metadata.json file in a git tree.
   497→// If metadata.json doesn't exist (shadow branches), it falls back to detecting the agent
   498→// from the presence of agent-specific config files (.gemini/settings.json or .claude/).
   499→// Returns agent.AgentTypeUnknown if the agent type cannot be determined.
   500→func ReadAgentTypeFromTree(tree *object.Tree, checkpointPath string) agent.AgentType {
   501→	// First, try to read from metadata.json (present in condensed/committed checkpoints)
   502→	metadataPath := checkpointPath + "/" + paths.MetadataFileName
   503→	if file, err := tree.File(metadataPath); err == nil {
   504→		if content, err := file.Contents(); err == nil {
   505→			var metadata checkpoint.CommittedMetadata
   506→			if err := json.Unmarshal([]byte(content), &metadata); err == nil && metadata.Agent != "" {
   507→				return metadata.Agent
   508→			}
   509→		}
   510→	}
   511→
   512→	// Fall back to detecting agent from config files (shadow branches don't have metadata.json).
   513→	// Order: Gemini (most specific check), Claude (established default), OpenCode (newest/preview).
   514→	if _, err := tree.File(".gemini/settings.json"); err == nil {
   515→		return agent.AgentTypeGemini
   516→	}
   517→	if _, err := tree.Tree(".claude"); err == nil {
   518→		return agent.AgentTypeClaudeCode
   519→	}
   520→	// OpenCode: .opencode directory or opencode.json config
   521→	if _, err := tree.Tree(".opencode"); err == nil {
   522→		return agent.AgentTypeOpenCode
   523→	}
   524→	if _, err := tree.File("opencode.json"); err == nil {
   525→		return agent.AgentTypeOpenCode
   526→	}
   527→
   528→	return agent.AgentTypeUnknown
   529→}
