   589→// OpenRepository opens the git repository with linked worktree support enabled.
   590→// It uses git.PlainOpenWithOptions with EnableDotGitCommonDir set to true,
   591→// which is required for proper operation in git worktrees created via 'git worktree add'.
   592→//
   593→// Without EnableDotGitCommonDir, go-git operations in worktrees can silently fail:
   594→// - Commits appear to succeed but are not persisted
   595→// - Refs are written to incorrect locations
   596→// - The worktree's HEAD/index don't get updated properly
   597→//
   598→// This happens because worktrees use .git as a file (pointing to the main repo)
   599→// rather than a directory, and go-git needs to route paths correctly between
   600→// shared (.git/) and per-worktree (.git/worktrees/<name>/) locations.
   601→//
   602→// The function first uses 'git rev-parse --show-toplevel' to find the repository
   603→// root, which works correctly even when called from a subdirectory within the repo.
   604→func OpenRepository(ctx context.Context) (*git.Repository, error) {
   605→	repoRoot, err := paths.WorktreeRoot(ctx)
   606→	if err != nil {
   607→		// Fallback to current directory if git command fails
   608→		// (e.g., if git is not installed or we're not in a repo)
   609→		repoRoot = "."
   610→	}
   611→
   612→	repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{
   613→		EnableDotGitCommonDir: true,
   614→	})
   615→	if err != nil {
   616→		return nil, fmt.Errorf("failed to open repository: %w", err)
   617→	}
   618→	return repo, nil
   619→}
   620→
   621→// IsInsideWorktree returns true if the current directory is inside a git worktree
   622→// (as opposed to the main repository). Worktrees have .git as a file pointing
   623→// to the main repo, while the main repo has .git as a directory.
   624→// This function works correctly from any subdirectory within the repository.
   625→func IsInsideWorktree(ctx context.Context) bool {
   626→	// First find the repository root
   627→	repoRoot, err := paths.WorktreeRoot(ctx)
   628→	if err != nil {
   629→		return false
   630→	}
   631→
   632→	gitPath := filepath.Join(repoRoot, gitDir)
   633→	gitInfo, err := os.Stat(gitPath)
   634→	if err != nil {
   635→		return false
   636→	}
   637→	return !gitInfo.IsDir()
   638→}
   639→
   640→// GetMainRepoRoot returns the root directory of the main repository.
   641→// In the main repo, this is the worktree path (repo root).
   642→// In a worktree, this parses the .git file to find the main repo.
   643→// This function works correctly from any subdirectory within the repository.
   644→//
   645→// Per gitrepository-layout(5), a worktree's .git file is a "gitfile" containing
   646→// "gitdir: <path>" pointing to $GIT_DIR/worktrees/<id> in the main repository.
   647→// See: https://git-scm.com/docs/gitrepository-layout
   648→func GetMainRepoRoot(ctx context.Context) (string, error) {
   649→	// First find the worktree/repo root
   650→	repoRoot, err := paths.WorktreeRoot(ctx)
   651→	if err != nil {
   652→		return "", fmt.Errorf("failed to get worktree path: %w", err)
   653→	}
   654→
   655→	if !IsInsideWorktree(ctx) {
   656→		return repoRoot, nil
   657→	}
   658→
   659→	// Worktree .git file contains: "gitdir: /path/to/main/.git/worktrees/<id>"
   660→	gitFilePath := filepath.Join(repoRoot, gitDir)
   661→	content, err := os.ReadFile(gitFilePath) //nolint:gosec // G304: gitFilePath is constructed from repo root, not user input
   662→	if err != nil {
   663→		return "", fmt.Errorf("failed to read .git file: %w", err)
   664→	}
   665→
   666→	gitdir := strings.TrimSpace(string(content))
   667→	gitdir = strings.TrimPrefix(gitdir, "gitdir: ")
   668→
   669→	// Extract main repo root: everything before "/.git/"
   670→	idx := strings.LastIndex(gitdir, "/.git/")
   671→	if idx < 0 {
   672→		return "", fmt.Errorf("unexpected gitdir format: %s", gitdir)
   673→	}
   674→	return gitdir[:idx], nil
   675→}
   676→
   677→// GetGitCommonDir returns the path to the shared git directory.
   678→// In a regular checkout, this is .git/
   679→// In a worktree, this is the main repo's .git/ (not .git/worktrees/<name>/)
   680→// Uses git rev-parse --git-common-dir for reliable handling of worktrees.
   681→func GetGitCommonDir(ctx context.Context) (string, error) {
   682→	cmd := exec.CommandContext(ctx, "git", "rev-parse", "--git-common-dir")
   683→	cmd.Dir = "."
   684→	output, err := cmd.Output()
   685→	if err != nil {
   686→		return "", fmt.Errorf("failed to get git common dir: %w", err)
   687→	}
   688→
   689→	commonDir := strings.TrimSpace(string(output))
   690→
   691→	// git rev-parse --git-common-dir returns relative paths from the working directory,
   692→	// so we need to make it absolute if it isn't already
   693→	if !filepath.IsAbs(commonDir) {
   694→		commonDir = filepath.Join(".", commonDir)
   695→	}
   696→
   697→	return filepath.Clean(commonDir), nil
   698→}
   699→
   700→// EnsureEntireGitignore ensures all required entries are in .entire/.gitignore
   701→// Works correctly from any subdirectory within the repository.
   702→func EnsureEntireGitignore(ctx context.Context) error {
   703→	// Get absolute path for the gitignore file
   704→	gitignoreAbs, err := paths.AbsPath(ctx, entireGitignore)
   705→	if err != nil {
   706→		gitignoreAbs = entireGitignore // Fallback to relative
   707→	}
   708→
   709→	// Read existing content
   710→	var content string
   711→	if data, err := os.ReadFile(gitignoreAbs); err == nil { //nolint:gosec // path is from AbsPath or constant
   712→		content = string(data)
   713→	}
   714→
   715→	// All entries that should be in .entire/.gitignore
   716→	requiredEntries := []string{
   717→		"tmp/",
   718→		"settings.local.json",
   719→		"metadata/",
   720→		"logs/",
   721→	}
   722→
   723→	// Track what needs to be added
   724→	var toAdd []string
   725→	for _, entry := range requiredEntries {
   726→		if !strings.Contains(content, entry) {
   727→			toAdd = append(toAdd, entry)
   728→		}
   729→	}
   730→
   731→	// Nothing to add
   732→	if len(toAdd) == 0 {
   733→		return nil
   734→	}
   735→
   736→	// Ensure .entire directory exists
   737→	if err := os.MkdirAll(filepath.Dir(gitignoreAbs), 0o750); err != nil {
   738→		return fmt.Errorf("failed to create .entire directory: %w", err)
   739→	}
   740→
   741→	// Append missing entries to gitignore
   742→	var sb strings.Builder
   743→	for _, entry := range toAdd {
   744→		sb.WriteString(entry + "\n")
   745→	}
   746→	content += sb.String()
   747→
   748→	if err := os.WriteFile(gitignoreAbs, []byte(content), 0o644); err != nil { //nolint:gosec // path is from AbsPath or constant
   749→		return fmt.Errorf("failed to write gitignore: %w", err)
   750→	}
   751→	return nil
   752→}
