  1127→// ErrBranchNotFound is returned by DeleteBranchCLI when the branch does not exist.
  1128→var ErrBranchNotFound = errors.New("branch not found")
  1129→
  1130→// DeleteBranchCLI deletes a git branch using the git CLI.
  1131→// Uses `git branch -D` instead of go-git's RemoveReference because go-git v5
  1132→// doesn't properly persist deletions when refs are packed (.git/packed-refs)
  1133→// or in a worktree context. This is the same class of go-git v5 bug that
  1134→// affects checkout and reset --hard (see HardResetWithProtection).
  1135→//
  1136→// Returns ErrBranchNotFound if the branch does not exist, allowing callers
  1137→// to use errors.Is for idempotent deletion patterns.
  1138→func DeleteBranchCLI(ctx context.Context, branchName string) error {
  1139→	// Pre-check: verify the branch exists so callers get a structured error
  1140→	// instead of parsing git's output string (which varies across locales).
  1141→	// git show-ref exits 1 for "not found" and 128+ for fatal errors (corrupt
  1142→	// repo, permissions, not a git directory). Only map exit code 1 to
  1143→	// ErrBranchNotFound; propagate other failures as-is.
  1144→	check := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName)
  1145→	if err := check.Run(); err != nil {
  1146→		var exitErr *exec.ExitError
  1147→		if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 {
  1148→			return fmt.Errorf("%w: %s", ErrBranchNotFound, branchName)
  1149→		}
  1150→		return fmt.Errorf("failed to check branch %s: %w", branchName, err)
  1151→	}
  1152→
  1153→	cmd := exec.CommandContext(ctx, "git", "branch", "-D", "--", branchName)
  1154→	if output, err := cmd.CombinedOutput(); err != nil {
  1155→		return fmt.Errorf("failed to delete branch %s: %s: %w", branchName, strings.TrimSpace(string(output)), err)
  1156→	}
  1157→	return nil
  1158→}
