  1170→// HardResetWithProtection performs a git reset --hard to the specified commit.
  1171→// Uses the git CLI instead of go-git because go-git's HardReset incorrectly
  1172→// deletes untracked directories (like .entire/) even when they're in .gitignore.
  1173→// Returns the short commit ID (7 chars) on success for display purposes.
  1174→func HardResetWithProtection(ctx context.Context, commitHash plumbing.Hash) (shortID string, err error) {
  1175→	hashStr := commitHash.String()
  1176→	cmd := exec.CommandContext(ctx, "git", "reset", "--hard", hashStr)
  1177→	if output, err := cmd.CombinedOutput(); err != nil {
  1178→		return "", fmt.Errorf("reset failed: %s: %w", strings.TrimSpace(string(output)), err)
  1179→	}
  1180→
  1181→	// Return short commit ID for display
  1182→	shortID = hashStr
  1183→	if len(shortID) > 7 {
  1184→		shortID = shortID[:7]
  1185→	}
  1186→	return shortID, nil
  1187→}
