  1189→// collectUntrackedFiles collects untracked files in the working directory that are
  1190→// NOT ignored by .gitignore. This is used to capture the initial state when starting
  1191→// a session, ensuring untracked files present at session start are preserved during rewind.
  1192→// Uses "git ls-files --others --exclude-standard -z" to respect .gitignore rules,
  1193→// avoiding bloated session state from large ignored directories like node_modules/.
  1194→// Returns paths relative to the repository root.
  1195→func collectUntrackedFiles(ctx context.Context) ([]string, error) {
  1196→	repoRoot, err := paths.WorktreeRoot(ctx)
  1197→	if err != nil {
  1198→		repoRoot = "."
  1199→	}
  1200→
  1201→	cmd := exec.CommandContext(ctx, "git", "ls-files", "--others", "--exclude-standard", "-z")
  1202→	cmd.Dir = repoRoot
  1203→	output, err := cmd.Output()
  1204→	if err != nil {
  1205→		var exitErr *exec.ExitError
  1206→		if errors.As(err, &exitErr) {
  1207→			return nil, fmt.Errorf("git ls-files failed: %s: %w", strings.TrimSpace(string(exitErr.Stderr)), err)
  1208→		}
  1209→		return nil, fmt.Errorf("git ls-files failed: %w", err)
  1210→	}
  1211→
  1212→	raw := string(output)
  1213→	if raw == "" {
  1214→		return nil, nil
  1215→	}
  1216→
  1217→	var files []string
  1218→	for _, f := range strings.Split(raw, "\x00") {
  1219→		// Defense-in-depth: filter protected paths even though --exclude-standard should already handle them
  1220→		if f != "" && !isProtectedPath(f) {
  1221→			files = append(files, f)
  1222→		}
  1223→	}
  1224→	return files, nil
  1225→}
