  1227→// ExtractSessionIDFromCommit extracts the session ID from a commit's trailers.
  1228→// It checks the Entire-Session trailer first, then falls back to extracting from
  1229→// the metadata directory path in the Entire-Metadata trailer.
  1230→// Returns empty string if no session ID is found.
  1231→func ExtractSessionIDFromCommit(commit *object.Commit) string {
  1232→	// Try Entire-Session trailer first
  1233→	if sessionID, found := trailers.ParseSession(commit.Message); found {
  1234→		return sessionID
  1235→	}
  1236→
  1237→	// Try extracting from metadata directory (last path component)
  1238→	if metadataDir, found := trailers.ParseMetadata(commit.Message); found {
  1239→		return filepath.Base(metadataDir)
  1240→	}
  1241→
  1242→	return ""
  1243→}
