  1254→// createCommit creates a commit object
  1255→func createCommit(repo *git.Repository, treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) { //nolint:unparam // already present in codebase
  1256→	now := time.Now()
  1257→	sig := object.Signature{
  1258→		Name:  authorName,
  1259→		Email: authorEmail,
  1260→		When:  now,
  1261→	}
  1262→
  1263→	commit := &object.Commit{
  1264→		TreeHash:  treeHash,
  1265→		Author:    sig,
  1266→		Committer: sig,
  1267→		Message:   message,
  1268→	}
  1269→
  1270→	// Add parent if not a new branch
  1271→	if parentHash != plumbing.ZeroHash {
  1272→		commit.ParentHashes = []plumbing.Hash{parentHash}
  1273→	}
  1274→
  1275→	obj := repo.Storer.NewEncodedObject()
  1276→	if err := commit.Encode(obj); err != nil {
  1277→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
  1278→	}
  1279→
  1280→	hash, err := repo.Storer.SetEncodedObject(obj)
  1281→	if err != nil {
  1282→		return plumbing.ZeroHash, fmt.Errorf("failed to store commit: %w", err)
  1283→	}
  1284→
  1285→	return hash, nil
  1286→}
