  1288→// getSessionDescriptionFromTree reads the first line of prompt.txt or context.md from a git tree.
  1289→// This is the tree-based equivalent of getSessionDescription (which reads from filesystem).
  1290→//
  1291→// If metadataDir is provided, looks for files at metadataDir/prompt.txt or metadataDir/context.md.
  1292→// If metadataDir is empty, first tries the root of the tree (for when the tree is already
  1293→// the session directory), then falls back to
  1294→// searching for .entire/metadata/*/prompt.txt or context.md (for full worktree trees).
  1295→func getSessionDescriptionFromTree(tree *object.Tree, metadataDir string) string {
  1296→	// Helper to read first line from a file in tree
  1297→	readFirstLine := func(path string) string {
  1298→		file, err := tree.File(path)
  1299→		if err != nil {
  1300→			return ""
  1301→		}
  1302→		content, err := file.Contents()
  1303→		if err != nil {
  1304→			return ""
  1305→		}
  1306→		lines := strings.SplitN(content, "\n", 2)
  1307→		if len(lines) > 0 && lines[0] != "" {
  1308→			desc := strings.TrimSpace(lines[0])
  1309→			// Remove markdown header prefix if present
  1310→			return strings.TrimPrefix(desc, "# ")
  1311→		}
  1312→		return ""
  1313→	}
  1314→
  1315→	// If metadataDir is provided, look there directly
  1316→	if metadataDir != "" {
  1317→		if desc := readFirstLine(metadataDir + "/" + paths.PromptFileName); desc != "" {
  1318→			return desc
  1319→		}
  1320→		if desc := readFirstLine(metadataDir + "/" + paths.ContextFileName); desc != "" {
  1321→			return desc
  1322→		}
  1323→		return NoDescription
  1324→	}
  1325→
  1326→	// No metadataDir provided - first try looking at the root of the tree
  1327→	// (used when the tree is already the session directory)
  1328→	if desc := readFirstLine(paths.PromptFileName); desc != "" {
  1329→		return desc
  1330→	}
  1331→	if desc := readFirstLine(paths.ContextFileName); desc != "" {
  1332→		return desc
  1333→	}
  1334→
  1335→	// Fall back to searching for .entire/metadata/*/prompt.txt or context.md
  1336→	// (used when the tree is the full worktree)
  1337→	var desc string
  1338→	//nolint:errcheck // We ignore errors here as we're just searching for a description
  1339→	_ = tree.Files().ForEach(func(f *object.File) error {
  1340→		if desc != "" {
  1341→			return nil // Already found description
  1342→		}
  1343→		name := f.Name
  1344→		if strings.Contains(name, ".entire/metadata/") {
  1345→			if strings.HasSuffix(name, "/"+paths.PromptFileName) || strings.HasSuffix(name, "/"+paths.ContextFileName) {
  1346→				content, err := f.Contents()
  1347→				if err != nil {
  1348→					return nil //nolint:nilerr // Skip files we can't read, continue searching
  1349→				}
  1350→				lines := strings.SplitN(content, "\n", 2)
  1351→				if len(lines) > 0 && lines[0] != "" {
  1352→					desc = strings.TrimSpace(lines[0])
  1353→					desc = strings.TrimPrefix(desc, "# ")
  1354→				}
  1355→			}
  1356→		}
  1357→		return nil
  1358→	})
  1359→
  1360→	if desc != "" {
  1361→		return desc
  1362→	}
  1363→	return NoDescription
  1364→}
