   598→func TestAppendShellCompletion(t *testing.T) {
   599→	tests := []struct {
   600→		name           string
   601→		rcFileRelPath  string
   602→		completionLine string
   603→		preExisting    string // existing content in rc file; empty means file doesn't exist
   604→		createParent   bool   // whether parent dir already exists
   605→	}{
   606→		{
   607→			name:           "zsh_new_file",
   608→			rcFileRelPath:  ".zshrc",
   609→			completionLine: "source <(entire completion zsh)",
   610→			createParent:   true,
   611→		},
   612→		{
   613→			name:           "zsh_existing_file",
   614→			rcFileRelPath:  ".zshrc",
   615→			completionLine: "source <(entire completion zsh)",
   616→			preExisting:    "# existing zshrc content\n",
   617→			createParent:   true,
   618→		},
   619→		{
   620→			name:           "fish_no_parent_dir",
   621→			rcFileRelPath:  filepath.Join(".config", "fish", "config.fish"),
   622→			completionLine: "entire completion fish | source",
   623→			createParent:   false,
   624→		},
   625→		{
   626→			name:           "fish_existing_dir",
   627→			rcFileRelPath:  filepath.Join(".config", "fish", "config.fish"),
   628→			completionLine: "entire completion fish | source",
   629→			createParent:   true,
   630→		},
   631→	}
   632→
   633→	for _, tt := range tests {
   634→		t.Run(tt.name, func(t *testing.T) {
   635→			home := t.TempDir()
   636→			rcFile := filepath.Join(home, tt.rcFileRelPath)
   637→
   638→			if tt.createParent {
   639→				if err := os.MkdirAll(filepath.Dir(rcFile), 0o755); err != nil {
   640→					t.Fatal(err)
   641→				}
   642→			}
   643→			if tt.preExisting != "" {
   644→				if err := os.WriteFile(rcFile, []byte(tt.preExisting), 0o644); err != nil {
   645→					t.Fatal(err)
   646→				}
   647→			}
