			want:    "",
		},
		{
			name:    "whitespace around command",
			content: "#!/bin/sh\n# comment\n  entire hooks git commit-msg \"$1\" || exit 1  \n",
			want:    `entire hooks git commit-msg "$1" || exit 1`,
