   166→			}
   167→
   168→			checkpointTree, cpTreeErr := repo.TreeObject(checkpointEntry.Hash)
   169→			if cpTreeErr != nil {
   170→				continue
   171→			}
   172→
   173→			// Reconstruct checkpoint ID: <bucket><remaining>
   174→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   175→			checkpointID, cpErr := id.NewCheckpointID(checkpointIDStr)
   176→			if cpErr != nil {
   177→				// Skip invalid checkpoint IDs
   178→				continue
   179→			}
   180→
   181→			info := CheckpointInfo{
   182→				CheckpointID: checkpointID,
   183→			}
   184→
   185→			// Get details from metadata file (CheckpointSummary format)
   186→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   187→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   188→					var summary checkpoint.CheckpointSummary
   189→					if json.Unmarshal([]byte(content), &summary) == nil && len(summary.Sessions) > 0 {
   190→						info.CheckpointsCount = summary.CheckpointsCount
   191→						info.FilesTouched = summary.FilesTouched
   192→						info.SessionCount = len(summary.Sessions)
   193→
   194→						// Read session-level metadata for Agent, SessionID, CreatedAt, SessionIDs
   195→						for i, sessionPaths := range summary.Sessions {
   196→							if sessionPaths.Metadata != "" {
   197→								// SessionFilePaths now contains absolute paths with leading "/"
   198→								// Strip the leading "/" for tree.File() which expects paths without leading slash
   199→								sessionMetadataPath := strings.TrimPrefix(sessionPaths.Metadata, "/")
   200→								if sessionFile, sErr := tree.File(sessionMetadataPath); sErr == nil {
   201→									if sessionContent, scErr := sessionFile.Contents(); scErr == nil {
   202→										var sessionMetadata checkpoint.CommittedMetadata
   203→										if json.Unmarshal([]byte(sessionContent), &sessionMetadata) == nil {
   204→											info.SessionIDs = append(info.SessionIDs, sessionMetadata.SessionID)
   205→											// Use first session's metadata for Agent, SessionID, CreatedAt
   206→											if i == 0 {
   207→												info.Agent = sessionMetadata.Agent
   208→												info.SessionID = sessionMetadata.SessionID
   209→												info.CreatedAt = sessionMetadata.CreatedAt
   210→												info.IsTask = sessionMetadata.IsTask
   211→												info.ToolUseID = sessionMetadata.ToolUseID
   212→											}
   213→										}
   214→									}
   215→								}
   216→							}
   217→						}
   218→					}
   219→				}
   220→			}
   221→
   222→			checkpoints = append(checkpoints, info)
   223→		}
   224→	}
   225→
   226→	// Sort by time (most recent first)
   227→	sort.Slice(checkpoints, func(i, j int) bool {
   228→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   229→	})
   230→
   231→	return checkpoints, nil
   232→}
