   241→// isProtectedPath returns true if relPath is inside a directory that should
   242→// never be modified or deleted during rewind or other destructive operations.
   243→// Protected directories include git internals, entire metadata, and all
   244→// registered agent config directories.
   245→func isProtectedPath(relPath string) bool {
   246→	for _, dir := range protectedDirs() {
   247→		if relPath == dir || strings.HasPrefix(relPath, dir+string(filepath.Separator)) {
   248→			return true
   249→		}
   250→	}
   251→	return false
   252→}
