   285→// EnsureMetadataBranch creates the local entire/checkpoints/v1 branch if it doesn't exist.
   286→// If the remote-tracking branch (origin/entire/checkpoints/v1) exists, creates the local
   287→// branch from it to preserve existing checkpoint data. Otherwise creates an empty orphan.
   288→func EnsureMetadataBranch(repo *git.Repository) error {
   289→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   290→
   291→	// Check if local branch already exists
   292→	_, err := repo.Reference(refName, true)
   293→	if err == nil {
   294→		return nil
   295→	}
   296→	if !errors.Is(err, plumbing.ErrReferenceNotFound) {
   297→		return fmt.Errorf("failed to check metadata branch: %w", err)
   298→	}
   299→
   300→	// Local branch doesn't exist — create from remote if available
   301→	remoteRefName := plumbing.NewRemoteReferenceName("origin", paths.MetadataBranchName)
   302→	remoteRef, remoteErr := repo.Reference(remoteRefName, true)
   303→	if remoteErr != nil && !errors.Is(remoteErr, plumbing.ErrReferenceNotFound) {
   304→		return fmt.Errorf("failed to check remote metadata branch: %w", remoteErr)
   305→	}
   306→	if remoteErr == nil {
   307→		ref := plumbing.NewHashReference(refName, remoteRef.Hash())
   308→		if err := repo.Storer.SetReference(ref); err != nil {
   309→			return fmt.Errorf("failed to create metadata branch from remote: %w", err)
   310→		}
   311→		fmt.Fprintf(os.Stderr, "✓ Created local branch '%s' from origin\n", paths.MetadataBranchName)
   312→		return nil
   313→	}
   314→
   315→	// No local or remote branch — create empty orphan
   316→	emptyTree := &object.Tree{Entries: []object.TreeEntry{}}
   317→	obj := repo.Storer.NewEncodedObject()
   318→	if err := emptyTree.Encode(obj); err != nil {
   319→		return fmt.Errorf("failed to encode empty tree: %w", err)
   320→	}
   321→	emptyTreeHash, err := repo.Storer.SetEncodedObject(obj)
   322→	if err != nil {
   323→		return fmt.Errorf("failed to store empty tree: %w", err)
   324→	}
   325→
   326→	// Create orphan commit (no parent)
   327→	now := time.Now()
   328→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
   329→	sig := object.Signature{
   330→		Name:  authorName,
   331→		Email: authorEmail,
   332→		When:  now,
   333→	}
   334→
   335→	commit := &object.Commit{
   336→		TreeHash:  emptyTreeHash,
   337→		Author:    sig,
   338→		Committer: sig,
   339→		Message:   "Initialize metadata branch\n\nThis branch stores session metadata.\n",
   340→	}
   341→	// Note: No ParentHashes - this is an orphan commit
   342→
   343→	commitObj := repo.Storer.NewEncodedObject()
   344→	if err := commit.Encode(commitObj); err != nil {
   345→		return fmt.Errorf("failed to encode orphan commit: %w", err)
   346→	}
   347→	commitHash, err := repo.Storer.SetEncodedObject(commitObj)
   348→	if err != nil {
   349→		return fmt.Errorf("failed to store orphan commit: %w", err)
   350→	}
   351→
   352→	// Create branch reference
   353→	ref := plumbing.NewHashReference(refName, commitHash)
   354→	if err := repo.Storer.SetReference(ref); err != nil {
   355→		return fmt.Errorf("failed to create metadata branch: %w", err)
   356→	}
   357→
   358→	fmt.Fprintf(os.Stderr, "✓ Created orphan branch '%s' for session metadata\n", paths.MetadataBranchName)
   359→	return nil
   360→}
