   450→// ExtractFirstPrompt extracts and truncates the first meaningful prompt from prompt content.
   451→// Prompts are separated by "\n\n---\n\n". Skips empty prompts and separator-only content.
   452→// Returns empty string if no valid prompt is found.
   453→func ExtractFirstPrompt(content string) string {
   454→	if content == "" {
   455→		return ""
   456→	}
   457→
   458→	// Prompts are separated by "\n\n---\n\n"
   459→	// Find the first non-empty prompt
   460→	prompts := strings.Split(content, "\n\n---\n\n")
   461→	var firstPrompt string
   462→	for _, p := range prompts {
   463→		cleaned := strings.TrimSpace(p)
   464→		// Skip empty prompts or prompts that are just dashes/separators
   465→		if cleaned == "" || isOnlySeparators(cleaned) {
   466→			continue
   467→		}
   468→		firstPrompt = cleaned
   469→		break
   470→	}
   471→
   472→	if firstPrompt == "" {
   473→		return ""
   474→	}
   475→
   476→	return TruncateDescription(firstPrompt, MaxDescriptionLength)
   477→}
