   531→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
   532→func isOnlySeparators(s string) bool {
   533→	for _, r := range s {
   534→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
   535→			return false
   536→		}
   537→	}
   538→	return true
   539→}
