   541→// ReadAllSessionPromptsFromTree reads the first prompt for all sessions in a multi-session checkpoint.
   542→// Returns a slice of prompts parallel to sessionIDs (oldest to newest).
   543→// For single-session checkpoints, returns a slice with just the root prompt.
   544→func ReadAllSessionPromptsFromTree(tree *object.Tree, checkpointPath string, sessionCount int, sessionIDs []string) []string {
   545→	if sessionCount <= 1 || len(sessionIDs) <= 1 {
   546→		// Single session - just return the root prompt
   547→		prompt := ReadSessionPromptFromTree(tree, checkpointPath)
   548→		if prompt != "" {
   549→			return []string{prompt}
   550→		}
   551→		return nil
   552→	}
   553→
   554→	// Multi-session: read prompts from archived folders (0/, 1/, etc.) and root
   555→	prompts := make([]string, len(sessionIDs))
   556→
   557→	// Read archived session prompts (folders 0, 1, ... N-2)
   558→	for i := range sessionCount - 1 {
   559→		archivedPath := fmt.Sprintf("%s/%d", checkpointPath, i)
   560→		prompts[i] = ReadSessionPromptFromTree(tree, archivedPath)
   561→	}
   562→
   563→	// Read the most recent session prompt (at root level)
   564→	prompts[len(prompts)-1] = ReadSessionPromptFromTree(tree, checkpointPath)
   565→
   566→	return prompts
   567→}
