   754→// checkCanRewindWithWarning checks working directory and returns a warning with diff stats.
   755→// Always returns canRewind=true but includes a warning message with +/- line stats for
   756→// uncommitted changes. Used by manual-commit strategy.
   757→func checkCanRewindWithWarning(ctx context.Context) (bool, string, error) {
   758→	repo, err := OpenRepository(ctx)
   759→	if err != nil {
   760→		// Can't open repo - still allow rewind but without stats
   761→		return true, "", nil //nolint:nilerr // Rewind allowed even if repo can't be opened
   762→	}
   763→
   764→	worktree, err := repo.Worktree()
   765→	if err != nil {
   766→		return true, "", nil //nolint:nilerr // Rewind allowed even if worktree can't be accessed
   767→	}
   768→
   769→	status, err := worktree.Status()
   770→	if err != nil {
   771→		return true, "", nil //nolint:nilerr // Rewind allowed even if status can't be retrieved
   772→	}
   773→
   774→	if status.IsClean() {
   775→		return true, "", nil
   776→	}
   777→
   778→	// Get HEAD commit tree for comparison - if we can't get it, just return without stats
   779→	head, err := repo.Head()
   780→	if err != nil {
   781→		return true, "", nil //nolint:nilerr // Rewind allowed even without HEAD (e.g., empty repo)
   782→	}
   783→
   784→	headCommit, err := repo.CommitObject(head.Hash())
   785→	if err != nil {
   786→		return true, "", nil //nolint:nilerr // Rewind allowed even if commit lookup fails
   787→	}
   788→
   789→	headTree, err := headCommit.Tree()
   790→	if err != nil {
   791→		return true, "", nil //nolint:nilerr // Rewind allowed even if tree lookup fails
   792→	}
   793→
   794→	type fileChange struct {
   795→		status   string // "modified", "added", "deleted"
   796→		added    int
   797→		removed  int
   798→		filename string
   799→	}
   800→
   801→	var changes []fileChange
   802→	// Use repo root, not cwd - git status returns paths relative to repo root
   803→	repoRoot, err := paths.WorktreeRoot(ctx)
   804→	if err != nil {
   805→		return true, "", nil //nolint:nilerr // Rewind allowed even if worktree root lookup fails
   806→	}
   807→
   808→	for file, st := range status {
   809→		// Skip .entire directory
   810→		if paths.IsInfrastructurePath(file) {
   811→			continue
   812→		}
   813→
   814→		// Skip untracked files
   815→		if st.Worktree == git.Untracked {
   816→			continue
   817→		}
   818→
   819→		var change fileChange
   820→		change.filename = file
   821→
   822→		switch {
   823→		case st.Staging == git.Added || st.Worktree == git.Added:
   824→			change.status = "added"
   825→			// New file - count all lines as added
   826→			absPath := filepath.Join(repoRoot, file)
   827→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
   828→				change.added = countLines(content)
   829→			}
   830→		case st.Staging == git.Deleted || st.Worktree == git.Deleted:
   831→			change.status = "deleted"
   832→			// Deleted file - count lines from HEAD as removed
   833→			if entry, err := headTree.File(file); err == nil {
   834→				if content, err := entry.Contents(); err == nil {
   835→					change.removed = countLines([]byte(content))
   836→				}
   837→			}
   838→		case st.Staging == git.Modified || st.Worktree == git.Modified:
   839→			change.status = "modified"
   840→			// Modified file - compute diff stats
   841→			var headContent, workContent []byte
   842→			if entry, err := headTree.File(file); err == nil {
   843→				if content, err := entry.Contents(); err == nil {
   844→					headContent = []byte(content)
   845→				}
   846→			}
   847→			absPath := filepath.Join(repoRoot, file)
   848→			if content, err := os.ReadFile(absPath); err == nil { //nolint:gosec // absPath is repo root + relative path from git status
   849→				workContent = content
   850→			}
   851→			if headContent != nil && workContent != nil {
   852→				change.added, change.removed = computeDiffStats(headContent, workContent)
   853→			}
   854→		default:
   855→			continue
   856→		}
   857→
   858→		changes = append(changes, change)
   859→	}
   860→
   861→	if len(changes) == 0 {
   862→		return true, "", nil
   863→	}
   864→
   865→	// Sort changes by filename for consistent output
   866→	sort.Slice(changes, func(i, j int) bool {
   867→		return changes[i].filename < changes[j].filename
   868→	})
   869→
   870→	var msg strings.Builder
   871→	msg.WriteString("The following uncommitted changes will be reverted:\n")
   872→
   873→	totalAdded, totalRemoved := 0, 0
   874→	for _, c := range changes {
   875→		totalAdded += c.added
   876→		totalRemoved += c.removed
   877→
   878→		var stats string
   879→		switch {
   880→		case c.added > 0 && c.removed > 0:
   881→			stats = fmt.Sprintf("+%d/-%d", c.added, c.removed)
   882→		case c.added > 0:
   883→			stats = fmt.Sprintf("+%d", c.added)
   884→		case c.removed > 0:
   885→			stats = fmt.Sprintf("-%d", c.removed)
   886→		}
   887→
   888→		fmt.Fprintf(&msg, "  %-10s %s", c.status+":", c.filename)
   889→		if stats != "" {
   890→			fmt.Fprintf(&msg, " (%s)", stats)
   891→		}
   892→		msg.WriteString("\n")
   893→	}
   894→
   895→	if totalAdded > 0 || totalRemoved > 0 {
   896→		fmt.Fprintf(&msg, "\nTotal: +%d/-%d lines\n", totalAdded, totalRemoved)
   897→	}
   898→
   899→	return true, msg.String(), nil
   900→}
