   902→// countLines counts the number of lines in content.
   903→func countLines(content []byte) int {
   904→	if len(content) == 0 {
   905→		return 0
   906→	}
   907→	count := 1
   908→	for _, b := range content {
   909→		if b == '\n' {
   910→			count++
   911→		}
   912→	}
   913→	// Don't count trailing newline as extra line
   914→	if len(content) > 0 && content[len(content)-1] == '\n' {
   915→		count--
   916→	}
   917→	return count
   918→}
   919→
   920→// computeDiffStats computes added and removed line counts between old and new content.
   921→// Uses a simple line-based diff algorithm.
   922→func computeDiffStats(oldContent, newContent []byte) (added, removed int) {
   923→	oldLines := splitLines(oldContent)
   924→	newLines := splitLines(newContent)
   925→
   926→	// Build a set of old lines with counts
   927→	oldSet := make(map[string]int)
   928→	for _, line := range oldLines {
   929→		oldSet[line]++
   930→	}
   931→
   932→	// Check which new lines are truly new
   933→	for _, line := range newLines {
   934→		if oldSet[line] > 0 {
   935→			oldSet[line]--
   936→		} else {
   937→			added++
   938→		}
   939→	}
   940→
   941→	// Remaining old lines are removed
   942→	for _, count := range oldSet {
   943→		removed += count
   944→	}
   945→
   946→	return added, removed
   947→}
   948→
   949→// splitLines splits content into lines, preserving empty lines.
   950→func splitLines(content []byte) []string {
   951→	if len(content) == 0 {
   952→		return nil
   953→	}
   954→	s := string(content)
   955→	// Remove trailing newline to avoid empty last element
   956→	s = strings.TrimSuffix(s, "\n")
   957→	return strings.Split(s, "\n")
   958→}
