  1160→// branchExistsCLI checks if a branch exists using git CLI.
  1161→// Returns nil if the branch exists, or an error if it does not.
  1162→func branchExistsCLI(ctx context.Context, branchName string) error {
  1163→	cmd := exec.CommandContext(ctx, "git", "show-ref", "--verify", "--quiet", "refs/heads/"+branchName)
  1164→	if err := cmd.Run(); err != nil {
  1165→		return fmt.Errorf("branch %s not found: %w", branchName, err)
  1166→	}
  1167→	return nil
  1168→}
