  1366→// GetGitAuthorFromRepo retrieves the git user.name and user.email,
  1367→// checking both the repository-local config and the global ~/.gitconfig.
  1368→// Delegates to checkpoint.GetGitAuthorFromRepo — this wrapper exists so
  1369→// callers within the strategy package don't need a qualified import.
  1370→func GetGitAuthorFromRepo(repo *git.Repository) (name, email string) {
  1371→	return checkpoint.GetGitAuthorFromRepo(repo)
