  1374→// GetCurrentBranchName returns the short name of the current branch if HEAD points to a branch.
  1375→// Returns an empty string if in detached HEAD state or if there's an error reading HEAD.
  1376→// This is used to capture branch metadata for checkpoints.
  1377→func GetCurrentBranchName(repo *git.Repository) string {
  1378→	head, err := repo.Head()
  1379→	if err != nil || !head.Name().IsBranch() {
  1380→		return ""
  1381→	}
  1382→	return head.Name().Short()
  1383→}
  1384→
  1385→// getMainBranchHash returns the hash of the main branch (main or master).
  1386→// Returns ZeroHash if no main branch is found.
  1387→func GetMainBranchHash(repo *git.Repository) plumbing.Hash {
  1388→	// Try common main branch names
  1389→	for _, branchName := range []string{branchMain, branchMaster} {
  1390→		// Try local branch first
  1391→		ref, err := repo.Reference(plumbing.NewBranchReferenceName(branchName), true)
  1392→		if err == nil {
  1393→			return ref.Hash()
  1394→		}
  1395→		// Try remote tracking branch
  1396→		ref, err = repo.Reference(plumbing.NewRemoteReferenceName("origin", branchName), true)
  1397→		if err == nil {
  1398→			return ref.Hash()
  1399→		}
  1400→	}
  1401→	return plumbing.ZeroHash
  1402→}
  1403→
  1404→// GetDefaultBranchName returns the name of the default branch.
  1405→// First checks origin/HEAD, then falls back to checking if main/master exists.
  1406→// Returns empty string if unable to determine.
  1407→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1408→func GetDefaultBranchName(repo *git.Repository) string {
  1409→	// Try to get the symbolic reference for origin/HEAD
  1410→	// Use resolved=false to get the symbolic ref itself, then extract its target
  1411→	ref, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", "HEAD"), false)
  1412→	if err == nil && ref != nil && ref.Type() == plumbing.SymbolicReference {
  1413→		target := ref.Target().String()
  1414→		if branchName, found := strings.CutPrefix(target, "refs/remotes/origin/"); found {
  1415→			return branchName
  1416→		}
  1417→	}
  1418→
  1419→	// Fallback: check if origin/main or origin/master exists
  1420→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMain), true); err == nil {
  1421→		return branchMain
  1422→	}
  1423→	if _, err := repo.Reference(plumbing.NewRemoteReferenceName("origin", branchMaster), true); err == nil {
  1424→		return branchMaster
  1425→	}
  1426→
  1427→	// Final fallback: check local branches
  1428→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMain), true); err == nil {
  1429→		return branchMain
  1430→	}
  1431→	if _, err := repo.Reference(plumbing.NewBranchReferenceName(branchMaster), true); err == nil {
  1432→		return branchMaster
  1433→	}
  1434→
  1435→	return ""
  1436→}
  1437→
  1438→// IsOnDefaultBranch checks if the repository HEAD is on the default branch.
  1439→// Returns (isOnDefault, currentBranchName).
  1440→// NOTE: Duplicated from cli/git_operations.go - see ENT-129 for consolidation.
  1441→func IsOnDefaultBranch(repo *git.Repository) (bool, string) {
  1442→	currentBranch := GetCurrentBranchName(repo)
  1443→	if currentBranch == "" {
  1444→		return false, ""
  1445→	}
  1446→
  1447→	defaultBranch := GetDefaultBranchName(repo)
  1448→	if defaultBranch == "" {
  1449→		// Can't determine default, check common names
  1450→		if currentBranch == branchMain || currentBranch == branchMaster {
  1451→			return true, currentBranch
  1452→		}
  1453→		return false, currentBranch
  1454→	}
  1455→
  1456→	return currentBranch == defaultBranch, currentBranch
  1457→}
