  1461→// they are read (e.g., OpenCode creates its transcript lazily via `opencode export`).
  1462→// Errors are silently ignored — this is best-effort for hook paths.
  1463→func prepareTranscriptIfNeeded(ctx context.Context, ag agent.Agent, transcriptPath string) {
