	}

	// Relative core.hooksPath should resolve relative to repo root.
	cmd = exec.CommandContext(ctx, "git", "config", "core.hooksPath", ".githooks")
	cmd.Dir = tmpDir
	if err := cmd.Run(); err != nil {
