	tests := []struct {
		input string
		want  string
	}{
		{"/usr/local/bin/entire", "'/usr/local/bin/entire'"},
		{"/Users/John O'Brien/bin/entire", "'/Users/John O'\\''Brien/bin/entire'"},
		{"/path with spaces/entire", "'/path with spaces/entire'"},
		{"/simple", "'/simple'"},
	}

