	cmd.Dir = worktreeDir
	output, err := cmd.Output()
	if err != nil {
		t.Fatalf("failed to get worktree git dir: %v", err)
	}
	worktreeGitDir := strings.TrimSpace(string(output))
	if !filepath.IsAbs(worktreeGitDir) {
