	cmd := exec.CommandContext(ctx, "git", "config", "core.hooksPath", ".husky/_")
	cmd.Dir = tmpDir
	if err := cmd.Run(); err != nil {
		t.Fatalf("failed to set core.hooksPath: %v", err)
	}

